path = pathlib.Path("research/devi-kavacham-sourcing.json")
data = json.loads(path.read_text())

idx = {v["stanza_number"]: i for i, v in enumerate(data["verses"])}

for row in DATA:
    sn, en, hi, te, ta = row
    i = idx[sn]
    data["verses"][i]["meaning_en"] = en
    data["verses"][i]["meaning_hi"] = hi
    data["verses"][i]["meaning_te"] = te
    data["verses"][i]["meaning_ta"] = ta
    data["verses"][i]["meaning_sources"] = {
        "en": SRC, "hi": SRC, "te": SRC, "ta": SRC
    }

# verify all filled
nulls = [v["stanza_number"] for v in data["verses"] if not v["meaning_en"]]
if nulls:
    print(f"WARNING: null meanings in stanzas {nulls}")
else:
    print(f"All {len(data['verses'])} stanzas filled.")

data["unresolved_flags"] = [
    f for f in data.get("unresolved_flags", [])
    if "meaning" not in f.lower()
]

path.write_text(json.dumps(data, ensure_ascii=False, indent=2))
print(f"Written: {path}")
